/* 玄玑 · 八字 · 大运判词（内容归主站，不进开源排盘服务）
   文案＝《大运判词·五档文案 v1》09-30；档位＝排盘服务给的 tier（0 上上 ≥90／1 上 75-89／2 中 60-74／3 下 45-59／4 下下 <45，方案 A）。
   取词：按大运干支哈希取三条之一；同一张盘里同档的几步运尽量不撞词（按运序依次让开），所以同一盘同一步运永远是同一条。 */
(function (g) {
  const WORDS = [
    [['如鱼得水', '大势在我', '这十年路子顺、帮手多，想做的事尽管放手去做。'],
     ['鸿运当头', '事半功倍', '同样的力气这十年最出活，适合把最重要的事排进来。'],
     ['顺风顺水', '贵人相扶', '做事总有人搭把手，别一个人硬扛，开口就有人应。']],
    [['财禄丰盈', '顺心顺意', '进账和心情都在线，守住节奏别折腾，就是好年景。'],
     ['稳步登高', '渐入佳境', '一步一个台阶往上走，别急，这十年的积累都算数。'],
     ['春风得意', '取舍有度', '机会不少，挑最对的那几个抓住，比全抓更赚。']],
    [['精进不休', '思稳行正', '平平常常才是真，这十年练本事比追结果划算。'],
     ['蓄势积能', '厚植根基', '不是没机会，是在攒本钱，根扎深了后面才接得住。'],
     ['稳扎稳打', '小步向前', '别指望一口吃胖，每月进步一点，十年下来很可观。']],
    [['自在随缘', '当放则放', '有些劲使不上就先不使，省下来的力气也是赚。'],
     ['以退为进', '守中待变', '这十年守比攻划算，把手里的看好，时机到了再动。'],
     ['慢行看路', '少即是多', '步子放慢不吃亏，少踩一个坑，就多一分赢面。']],
    [['守成蓄力', '静待其时', '这十年不拼速度拼耐力，把身体和本钱养好，就是赢。'],
     ['潜龙在渊', '养精蓄锐', '不是不行，是时候没到；沉住气的人，后面翻身最狠。'],
     ['蛰居练功', '寒冬育种', '外面冷就在屋里练功，这十年攒下的，都是下个十年的本钱。']],
  ];

  function hash(str) {
    let h = 0x811c9dc5;
    for (const ch of String(str)) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
    return h;
  }

  // cycles：排盘服务 bazi.luck.cycles（整张盘的全部大运，按运序）→ 每步 {title:[四字,四字], line}
  function luckWords(cycles) {
    const used = [new Set(), new Set(), new Set(), new Set(), new Set()];
    return (cycles || []).map((c) => {
      const t = c.tier;
      if (t == null || !WORDS[t]) return null;
      let i = hash(c.ganZhi) % 3;
      for (let k = 0; k < 3 && used[t].has(i); k++) i = (i + 1) % 3;
      used[t].add(i);
      if (used[t].size === 3) used[t].clear();
      const w = WORDS[t][i];
      return { title: [w[0], w[1]], line: w[2] };
    });
  }

  g.XuanjiBazi = Object.assign(g.XuanjiBazi || {}, { luckWords });
})(window);
